update public.spell_catalog set name_ru='Барьер клинков', casting_time='Действие', spell_range='90 футов', area='Стена до 100×20×5 футов или кольцо диаметром до 60 футов, высотой 20 и толщиной 5 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, concentration=true, ritual=false, check_type='Спасбросок Ловкости; не чаще 1 раза за ход на существо', damage='6к10 силового; половина при успехе', effect_summary='Создаёшь стену вращающихся магических клинков. Она даёт укрытие на три четверти, а её пространство является труднопроходимой местностью. Существо делает спасбросок при появлении в стене, при входе в неё или если заканчивает там ход.', upcast='', notes='Одно существо делает этот спасбросок не чаще одного раза за ход.', author_description='Сто футов вращающихся клинков. Жрец называет это защитой. Я бы хотел познакомиться с человеком, которого он считает нападением.', author_comment='Если проход выглядит как мясорубка, не проверяй, насколько буквально магия понимает слово «барьер».' where slug='blade-barrier';
update public.spell_catalog set name_ru='Цепная молния', casting_time='Действие', spell_range='150 футов', area='Первая цель и до 3 дополнительных целей в 30 футах от неё', duration='Мгновенно', components=array['В','С','М'], material='три серебряные булавки', concentration=false, ritual=false, check_type='Спасбросок Ловкости каждой цели', damage='10к8 электричеством; половина при успехе', effect_summary='Молния поражает первую видимую цель, затем от неё перескакивают до трёх разрядов к другим выбранным целям в 30 футах. Целью может быть существо или объект. Каждая цель может быть поражена только одним разрядом.', upcast='+1 дополнительный разряд к ещё одной цели за каждый уровень ячейки выше 6.', notes='Дополнительные цели должны находиться в пределах 30 футов от первой цели, а не друг от друга.', author_description='Обычная молния, но с социальными навыками: сначала знакомится с одним врагом, потом просит представить ещё троих.', author_comment='Если противники стоят тесной компанией, магия просто помогает им разделить общую проблему.' where slug='chain-lightning';
update public.spell_catalog set name_ru='Круг смерти', casting_time='Действие', spell_range='150 футов', area='Сфера радиусом 60 футов', duration='Мгновенно', components=array['В','С','М'], material='порошок измельчённой чёрной жемчужины стоимостью 500+ зм', concentration=false, ritual=false, check_type='Спасбросок Телосложения', damage='8к8 некротического; половина при успехе', effect_summary='В выбранной точке расходится огромная сфера отрицательной энергии. Все существа внутри делают спасбросок Телосложения.', upcast='+2к8 урона за каждый уровень ячейки выше 6.', notes='Радиус 60 футов — заклинание не различает союзников и врагов.', author_description='Шестьдесят футов отрицательной энергии за пятьсот золотых жемчужного порошка. Некроманты тоже умеют превращать деньги в массовые проблемы.', author_comment='Перед применением пересчитай союзников в радиусе. После применения это может стать сложнее.' where slug='circle-of-death';
update public.spell_catalog set name_ru='Призыв феи', casting_time='Действие', spell_range='60 футов', area='1 свободное место; дух действует в радиусе 5 футов от себя', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, concentration=true, ritual=false, check_type='Рукопашная атака заклинанием', damage='3к12 психического + модификатор характеристики заклинаний', effect_summary='Призываешь Среднего духа из Страны Фей. При появлении можешь совершить им рукопашную атаку заклинанием по существу в 5 футах. При попадании цель получает психический урон и становится Испуганной до начала твоего следующего хода, считая источником страха и тебя, и духа. В последующие ходы бонусным действием можешь телепортировать духа на 30 футов и повторить атаку.', upcast='+2к12 урона за каждый уровень ячейки выше 6.', notes='Телепортация духа и последующая атака выполняются одним Бонусным действием.', author_description='Вызываешь фейского духа, который появляется, бьёт по психике и тут же объясняет жертве, кого именно следует бояться. Редкая форма эффективного представления.', author_comment='Феи умеют произвести первое впечатление. Обычно последнее тоже.' where slug='conjure-fey';
update public.spell_catalog set name_ru='Предосторожность', casting_time='10 минут', spell_range='На себя', area='На себя', duration='10 дней', components=array['В','С','М'], material='украшенная драгоценными камнями статуэтка тебя стоимостью 1500+ зм', concentration=false, ritual=false, check_type='', damage='', effect_summary='Выбираешь известное тебе заклинание 5 уровня или ниже, которое накладывается Действием и может выбрать тебя целью. Во время сотворения Предосторожности тратишь ячейки и на оба заклинания, но вложенное заклинание не срабатывает сразу. Ты задаёшь условие; при первом его выполнении вложенное заклинание автоматически действует только на тебя, после чего Предосторожность заканчивается.', upcast='', notes='Одновременно может действовать только одна Предосторожность. Если наложить её снова, предыдущая заканчивается. Эффект также заканчивается, если материальная статуэтка перестаёт находиться при тебе.', author_description='Десять минут подготовки, две ячейки и полторы тысячи золотых в кармане — чтобы будущий ты смог автоматически исправить ошибку нынешнего тебя.', author_comment='Лучшее заклинание волшебника: заранее признать, что он обязательно попадёт в беду.' where slug='contingency';
update public.spell_catalog set name_ru='Создание нежити', casting_time='1 минута', spell_range='10 футов', area='До 3 трупов Средних или Маленьких гуманоидов', duration='Мгновенно; контроль 24 часа', components=array['В','С','М'], material='по одному чёрному ониксу стоимостью 150+ зм на каждый труп', concentration=false, ritual=false, check_type='', damage='', effect_summary='Накладывается только ночью. До трёх подходящих трупов становятся гулями под твоим контролем. Бонусным действием можно отдавать общий приказ любому числу созданных этим заклинанием существ в 120 футах. Без приказа они Уклоняются и двигаются только ради самосохранения. Контроль длится 24 часа; повторное наложение до его окончания продлевает контроль.', upcast='7 уровень: до 4 гулей. 8 уровень: до 5 гулей или 2 гастов/умертвий. 9 уровень: до 6 гулей, 3 гастов/умертвий или 2 мумий. Можно либо создавать, либо повторно подчинять соответствующее число существ.', notes='Повторное применение базовой ячейкой восстанавливает контроль до 3 ранее созданных существ. Заклинание можно сотворить только ночью.', author_description='Три трупа, одна минута и ночь — и у тебя появляется персонал, который не задаёт вопросов. До завтра. Потом вопросы начинаются у всех остальных.', author_comment='Если твоя рабочая сила требует ежегодной оценки, это неприятно. Если ежедневного переподчинения — ты некромант.' where slug='create-undead';
update public.spell_catalog set name_ru='Распад', casting_time='Действие', spell_range='60 футов', area='1 видимая цель', duration='Мгновенно', components=array['В','С','М'], material='магнитный камень и пыль', concentration=false, ritual=false, check_type='Существо: спасбросок Ловкости', damage='10к6 + 40 силового при провале', effect_summary='Зелёный луч поражает существо, немагический объект или создание магической силы. Существо при провале получает 10к6+40 силового урона. Если этот урон снижает его до 0 HP, оно и всё надетое/несомое немагическое снаряжение превращаются в серую пыль.', upcast='+3к6 урона за каждый уровень ячейки выше 6.', notes='Разрушенное таким образом существо можно вернуть только Истинным воскрешением или Желанием. Большой или меньший немагический объект/магическая сила уничтожается целиком; у Огромного или большего уничтожается куб 10 футов.', author_description='Луч, который решает спор между «вещь существует» и «вещи больше нет» в пользу второго варианта. Волшебники любят ясные результаты.', author_comment='Если после заклинания осталась аккуратная кучка серой пыли, это не уборка. Это улика.' where slug='disintegrate';
update public.spell_catalog set name_ru='Сглаз', casting_time='Действие', spell_range='На себя', area='Видимая цель в 60 футах; новые цели действием Магии', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, concentration=true, ritual=false, check_type='Спасбросок Мудрости', damage='', effect_summary='Выбираешь видимое существо в 60 футах и один эффект при провале: Сон — Бессознательное до урона или пробуждения действием; Паника — Испуг и обязательный Рывок от тебя по кратчайшему безопасному пути; Болезнь — Отравление. Каждый следующий ход действием Магии можешь выбрать новую цель.', upcast='', notes='Нельзя снова выбирать целью существо, которое уже успешно спаслось против этого применения. Паника заканчивается, если цель оказывается минимум в 60 футах от тебя и больше тебя не видит.', author_description='На минуту твой взгляд становится набором из сна, паники и тошноты. Некоторые люди достигают похожего эффекта одной репутацией.', author_comment='Если противник посмотрел тебе в глаза и сразу уснул, не воспринимай это как комплимент.' where slug='eyebite';
update public.spell_catalog set name_ru='Поиск пути', casting_time='1 минута', spell_range='На себя', area='Путь к знакомому месту', duration='Концентрация, до 1 дня', components=array['В','С','М'], material='набор инструментов для прорицания, например карты или руны, стоимостью 100+ зм', concentration=true, ritual=false, check_type='', damage='', effect_summary='Магически определяешь самый прямой физический маршрут к названному знакомому месту. Пока вы с целью на одном плане, знаешь расстояние и направление, а на развилках понимаешь, какой путь наиболее прямой.', upcast='', notes='Не работает для другого плана, движущегося места или неопределённой цели вроде «логова зелёного дракона». Нужно быть знакомым с конкретным местом.', author_description='Магия наконец отвечает на вопрос «куда идти» без загадок, стихов и божественных намёков. Следопыт, конечно, уже знал.', author_comment='Если заклинание показывает дорогу, а группа всё равно выбирает другую — экономь концентрацию, не нервы.' where slug='find-the-path';
update public.spell_catalog set name_ru='Плоть в камень', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты; при полной концентрации окаменение сохраняется', components=array['В','С','М'], material='перо кокатриса', concentration=true, ritual=false, check_type='Спасбросок Телосложения; повтор в конце каждого хода', damage='', effect_summary='При первом провале цель становится Опутанной; при успехе её Скорость равна 0 до начала твоего следующего хода. Опутанная цель в конце каждого хода повторяет спасбросок. Три успеха заканчивают заклинание, три провала превращают её в Окаменевшую.', upcast='', notes='Конструкты автоматически преуспевают в спасброске. Успехи и провалы не обязаны быть подряд. Если удерживать концентрацию полную минуту после окаменения, состояние остаётся до снятия Высшим восстановлением или подобной магией.', author_description='Процесс превращения человека в статую теперь включает счёт до трёх. Магия делает всё возможное, чтобы даже окаменение выглядело как бюрократия.', author_comment='Три провала — и спорить с тобой становится заметно сложнее. Хотя статуи обычно и раньше были хорошими слушателями.' where slug='flesh-to-stone';
update public.spell_catalog set name_ru='Запрет', casting_time='10 минут или ритуал', spell_range='Касание', area='До 40000 кв. футов пола и 30 футов высоты', duration='1 день', components=array['В','С','М'], material='рубиновая пыль стоимостью 1000+ зм', concentration=false, ritual=true, check_type='', damage='5к10 излучением или некротического выбранным типам существ при входе/окончании хода', effect_summary='Защищаешь огромную область от телепортации, порталов и межпланарного входа. Также выбираешь один или несколько типов: Аберрации, Небожители, Элементали, Феи, Исчадия, Нежить. Существо выбранного типа при первом входе за ход или окончании хода получает 5к10 выбранного при сотворении урона.', upcast='', notes='Можно задать пароль, защищающий от урона. Области двух Запретов не перекрываются. Если накладывать ежедневно 30 дней в одном месте, эффект становится постоянным до рассеивания; материальные компоненты расходуются при последнем, 30-м наложении.', author_description='Сорок тысяч квадратных футов официального «не входить через другие планы». Жрец наконец нашёл масштаб, соответствующий его чувству собственности.', author_comment='Если демону нужен пароль, чтобы войти без боли, это уже не храм. Это очень строгая проходная.' where slug='forbiddance';
